// 1. 获取输入节点数据
const ariaData = $input.first().json;

// 2. 基础信息提取
const parentName = $('开始').first().json.media || '未知资源';
const summary = ariaData.summary || '未命名';
const fileList = ariaData.details || [];
const fileCount = fileList.length;

// 3. 构建美观的标题
const formattedTitle = `🎬 ${parentName}`;

// 4. 构建美观的正文 (HTML 格式)
let contentHtml = "";

// 头部：资源简介
contentHtml += `<b>资源摘要：</b> ${summary}<br>`;
contentHtml += `<b>文件数量：</b> ${fileCount}<br>`;
contentHtml += `<hr>`; // 分割线

// 中间：带样式的列表
if (fileCount > 0) {
  const listItems = fileList.map((i, index) => {
    // 序号加粗，文件名放在代码块样式中（看起来更工整）
    const idx = (index + 1).toString().padStart(2, '0');
    return `<b>${idx}:</b> <code>  ${i.fileName}</code>`;
  });
  contentHtml += listItems.join('<br>');
} else {
  contentHtml += `<i>⚠️ 暂无有效文件清单</i>`;
}

// 尾部：时间戳
contentHtml += `<hr>`;
const now = new Date().toLocaleString('zh-CN', { hour12: false });
contentHtml += `<small style="color: gray;">📅 统计时间：${now}</small>`;

return {
  title: formattedTitle,
  content: contentHtml,
  template:"html"
};

// 1. 获取上一个节点的输出数据（n8n中$input.all()获取所有输入项）
const inputData = $input.all();
// 初始化存储网盘链接的数组
let tianyiLinkList = [];
let quarkLinkList = [];

// 2. 处理输入数据，先获取最外层的data数组
if (inputData && inputData.length > 0) {
  // 取第一个输入项的json数据（适配n8n的输出格式）
  const firstInput = inputData[0].json;
  const dataArray = firstInput.data || [];

  // 3. 循环data数组
  for (const dataItem of dataArray) {
    // 4. 判断list是否为空
    const list = dataItem.list || [];
    if (list.length === 0) {
      continue; // list为空则跳过当前data项
    }

    // 5. 循环非空的list数组
    for (const listItem of list) {
      const title = listItem.title || '';
      // 6. 判断title是否包含"影视名称
      if (title.toLowerCase().includes($('开始').first().json.media.toLowerCase())) {
        const cloudLinks = listItem.cloudLinks || [];
        // 7. 循环cloudLinks，筛选cloudType为'tianyi'或'quark'的link
        for (const linkItem of cloudLinks) {
          if (linkItem.link) {
            if (linkItem.cloudType === 'tianyi') {
              tianyiLinkList.push(linkItem.link); // 存入天翼云盘链接数组
            } else if (linkItem.cloudType === 'quark') {
              quarkLinkList.push(linkItem.link); // 存入夸克网盘链接数组
            }
          }
        }
      }
    }
  }

  // 8. 对链接数组进行去重处理（使用Set去重，再转回数组）
  const uniqueTianyiLinkList = [...new Set(tianyiLinkList)];
  const uniqueQuarkLinkList = [...new Set(quarkLinkList)];

  // 9. 提取链接中的分享码
  const tianyiShareCodeList = [];
  const quarkShareCodeList = [];

  // 天翼云盘分享码正则匹配（兼容两种格式：/t/xxx 和 /web/share?code=xxx）
  const tianyiShareCodeRegex = /https:\/\/cloud\.189\.cn\/(?:t\/|web\/share\?code=)([^&\/]+)/;

  // 夸克网盘分享码正则匹配（格式：/s/xxx）
  const quarkShareCodeRegex = /https:\/\/pan\.quark\.cn\/s\/([^&\/]+)/;

  console.log(`🔍 开始提取天翼云盘分享码，共有 ${uniqueTianyiLinkList.length} 个链接`);
  for (const link of uniqueTianyiLinkList) {
    const match = link.match(tianyiShareCodeRegex);
    if (match && match[1]) {
      const shareCode = match[1];
      // 过滤：只保留长度为12的分享码
      if (shareCode.length === 12) {
        tianyiShareCodeList.push(shareCode); // 提取天翼云盘分享码
        console.log(`✅ 保留天翼云盘分享码: ${shareCode} (长度: ${shareCode.length})`);
      } else {
        console.log(`⏭️ 过滤天翼云盘分享码: ${shareCode} (长度: ${shareCode.length}, 需要长度12)`);
      }
    }
  }

  console.log(`🔍 开始提取夸克网盘分享码，共有 ${uniqueQuarkLinkList.length} 个链接`);
  for (const link of uniqueQuarkLinkList) {
    const match = link.match(quarkShareCodeRegex);
    if (match && match[1]) {
      const shareCode = match[1];
      // 过滤：只保留长度为12的分享码
      if (shareCode.length === 12) {
        quarkShareCodeList.push(shareCode); // 提取夸克网盘分享码
        console.log(`✅ 保留夸克网盘分享码: ${shareCode} (长度: ${shareCode.length})`);
      } else {
        console.log(`⏭️ 过滤夸克网盘分享码: ${shareCode} (长度: ${shareCode.length}, 需要长度12)`);
      }
    }
  }

  // 计算总分享码数量
  const shareCodeCount = tianyiShareCodeList.length + quarkShareCodeList.length;

  console.log(`📊 分享码提取结果统计:`);
  console.log(`   天翼云盘分享码: ${tianyiShareCodeList.length} 个 (长度12)`);
  console.log(`   夸克网盘分享码: ${quarkShareCodeList.length} 个 (长度12)`);
  console.log(`   总计有效分享码: ${shareCodeCount} 个`);

  if (tianyiShareCodeList.length > 0) {
    console.log(`   天翼云盘分享码列表: ${tianyiShareCodeList.join(', ')}`);
  }
  if (quarkShareCodeList.length > 0) {
    console.log(`   夸克网盘分享码列表: ${quarkShareCodeList.join(', ')}`);
  }

  // 输出最终结果（n8n中通过return输出，供后续节点使用）
  return {
    tianyi: tianyiShareCodeList, // 天翼云盘分享码列表
    quark: quarkShareCodeList, // 夸克网盘分享码列表
    count: shareCodeCount // 总分享码数量
  };
} else {
  // 无输入数据时的兜底输出
  return {
    tianyi: [],
    quark: [],
    count: 0,
  };
}

// 1. 获取n8n查看遗漏集节点的输入数据
const inputData = $('过滤遗漏集').all();
// 初始化最终输出的结果数组
let result = [];

// 辅助函数：从S06E17格式的字符串中提取季数和集数
function extractSeasonEpisode(seStr) {
    const match = seStr.match(/S(\d+)E(\d+)/i);
    if (match) {
        return {
            season: match[1],
            episode: match[2]
        };
    }
    return null;
}

// 辅助函数：从aria2文件路径中提取季集信息
function extractEpisodeFromPath(path, mediaName) {
    if (!path || typeof path !== 'string') return null;

    // 检查路径是否包含指定的媒体名称
    if (!path.includes(mediaName)) return null;

    // 尝试匹配SxxExx格式
    const seMatch = path.match(/S\d+E\d+/i);
    if (seMatch) {
        return extractSeasonEpisode(seMatch[0]);
    }

    // 尝试匹配"第 x 集"格式
    const cnMatch = path.match(/第\s*(\d+)\s*集/i);
    if (cnMatch) {
        // 如果没有匹配到季数，默认为第1季
        return {
            season: "1",
            episode: cnMatch[1]
        };
    }

    return null;
}

// 2. 获取媒体名称用于匹配aria2文件
const mediaName = $('开始').first().json.media || '';
console.log(`📺 当前媒体名称: ${mediaName}`);

// 3. 从n8n节点获取Aria2任务数据，构建已存在任务的排除列表
let aria2ExcludedEpisodes = new Set();


try {
    // 获取Aria2下载任务节点数据
    const aria2DownloadData = $('Aria2下载任务').all();
    console.log(`📥 获取到Aria2下载任务数据条数: ${aria2DownloadData.length}`);

    // 处理Aria2下载任务
    for (const taskData of aria2DownloadData) {
        if (taskData.json && taskData.json.result && Array.isArray(taskData.json.result)) {
            for (const resultItem of taskData.json.result) {
                if (resultItem.files && Array.isArray(resultItem.files)) {
                    for (const file of resultItem.files) {
                        const episodeInfo = extractEpisodeFromPath(file.path, mediaName);
                        if (episodeInfo) {
                            const key = `S${episodeInfo.season.padStart(2, '0')}E${episodeInfo.episode.padStart(2, '0')}`;
                            aria2ExcludedEpisodes.add(key);
                            console.log(`❌ 排除Aria2下载任务中的剧集: ${key} (路径: ${file.path})`);
                        }
                    }
                }
            }
        }
    }

    // 获取Aria2等待任务节点数据
    const aria2WaitingData = $('Aria2等待任务').all();
    console.log(`📥 获取到Aria2等待任务数据条数: ${aria2WaitingData.length}`);

    // 处理Aria2等待任务
    for (const taskData of aria2WaitingData) {
        if (taskData.json && taskData.json.result && Array.isArray(taskData.json.result)) {
            for (const resultItem of taskData.json.result) {
                if (resultItem.files && Array.isArray(resultItem.files)) {
                    for (const file of resultItem.files) {
                        const episodeInfo = extractEpisodeFromPath(file.path, mediaName);
                        if (episodeInfo) {
                            const key = `S${episodeInfo.season.padStart(2, '0')}E${episodeInfo.episode.padStart(2, '0')}`;
                            aria2ExcludedEpisodes.add(key);
                            console.log(`❌ 排除Aria2等待任务中的剧集: ${key} (路径: ${file.path})`);
                        }
                    }
                }
            }
        }
    }

    console.log(`📊 总共排除 ${aria2ExcludedEpisodes.size} 个已有下载任务的剧集`);
    if (aria2ExcludedEpisodes.size > 0) {
        console.log(`📋 排除的剧集列表: ${Array.from(aria2ExcludedEpisodes).join(', ')}`);
    }
} catch (error) {
    console.error('❌ 处理Aria2任务数据时出错:', error.message);
    console.error('堆栈:', error.stack);
}

// 4. 校验输入数据是否有效
if (inputData && inputData.length > 0) {
    // 取第一个输入项的json数据（n8n标准格式）
    const firstInput = inputData[0].json;
    // 获取Items数组（核心数据）
    const items = firstInput.Items || [];

    console.log(`📋 从查看遗漏集节点获取到 ${items.length} 个剧集数据`);

    // 5. 遍历Items数组，提取所需字段
    for (const item of items) {
        // 提取季数（ParentIndexNumber）和集数（IndexNumber），并转为字符串
        const season = (item.ParentIndexNumber || '').toString();
        const index = (item.IndexNumber || '').toString();

        // 6. 仅当季数和集数都有值时，检查是否应该排除
        if (season && index) {
            // 构建与aria2中相同的格式用于比较
            const episodeKey = `S${season.padStart(2, '0')}E${index.padStart(2, '0')}`;

            // 检查是否在排除列表中
            if (aria2ExcludedEpisodes.has(episodeKey)) {
                console.log(`⏭️ 跳过已存在于aria2任务中的剧集: 第${season}季第${index}集 (${episodeKey})`);
                continue;
            }

            // 添加到结果数组
            result.push({
                s: season,
                e: index
            });

            console.log(`✅ 保留遗漏集: 第${season}季第${index}集`);
        }
    }
} else {
    console.warn('⚠️ 无效的输入数据或输入数据为空');
}

try {

    const embyData = $('检查Emby遗漏集').all();
    console.log(embyData)

	console.log(`📺 获取Emby检查结果: ${embyData.length} 条`);

    for (const item of embyData) {

        const data = item.json;
        console.log(data)

        const season = data.season;
        const episode = data.episode;
        const exists = data.exists;
        // 只处理不存在的
        if (exists) continue;

        // 构造 key
        const episodeKey =
            `S${String(season).padStart(2, '0')}` +
            `E${String(episode).padStart(2, '0')}`;

        // 如果已经在 aria2 里就跳过
        if (aria2ExcludedEpisodes.has(episodeKey)) {
            console.log(`⏭️ Emby存在但已在下载队列: ${episodeKey}`);
            continue;
        }

        // 加入结果集合（统一结构）
        result.push({
            s: season.toString(),
            e: episode.toString()
        });

        console.log(`📦 加入Emby遗漏集: ${episodeKey}`);
    }

} catch (error) {
    console.error('❌ Emby数据合并失败:', error.message);
}

console.log(`🎯 最终结果: ${result.length} 个遗漏剧集`);
// 7. 输出最终结果
return result;

const axios = require('axios');

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

console.log('==========================================');
console.log('📦 提取分享码信息脚本开始执行');
console.log('==========================================');

const startTime = Date.now();

const inputData = $input.all()[0]?.json || {};

const tianyiShareCodeList = inputData.tianyi || [];
const quarkShareCodeList = inputData.quark || [];
const totalCount = inputData.count || 0;

