const formatFileName = (fileName) => {
    const regex = /(S\d+)E(\d+).*\.([^.]+)$/i;
    const match = fileName.match(regex);
    if (match) {
        const fullSE = match[1] + "E" + match[2];
        const episodeNum = parseInt(match[2], 10);
        const extension = match[3];
        return $('开始').first().json.media + ` - ${fullSE} - 第 ${episodeNum} 集.${extension}`;
    } else {
        return fileName; // 匹配失败返回原名，不建议返回“格式匹配失败”以免文件名报错
    }
}

async function execute() {
    // 从转存节点获取输入数据
    const transferResults = $('转存').all();

    if (transferResults.length === 0 || !transferResults[0].json.success) {
        return [{ json: { status: "error", msg: "没有获取到转存结果或转存失败" } }];
    }

    const transferData = transferResults[0].json;
    const episodeDetails = transferData.details || [];
    // 1. 强制刷新 AList 目录
    try {
      await sleep(5000)
        await this.helpers.request({
            method: 'POST',
            uri: `http://192.168.3.31:5244/api/fs/list`,
            body: { path: "/tianyi", refresh: true },
            headers: { 'Authorization': CONFIG.alist.token },
            json: true
        });
        await this.helpers.request({
            method: 'POST',
            uri: `http://192.168.3.31:5244/api/fs/list`,
            body: { path: "/quark", refresh: true },
            headers: { 'Authorization': CONFIG.alist.token },
            json: true
        });
    } catch (e) {}

    const ariaMethods = [];
    const taskFileNames = [];
    const results = [];

    // 2. 收集任务
    console.log(`📥 从转存节点获取到 ${episodeDetails.length} 个剧集详情`);

    for (const episode of episodeDetails) {
        const type = episode.type; // tianyi 或 quark
        const fileName = episode.fileName; // 单个文件名
        const episodeCode = episode.episodeCode;

        if (!fileName) {
            console.log(`⚠️ 剧集 ${episodeCode} (${type}) 无fileName字段，跳过`);
            continue;
        }

        // 根据type确定路径前缀
        const pathPrefix = type === 'tianyi' ? '/tianyi' : '/quark';

        console.log(`📦 处理剧集: ${fileName} (${episodeCode}, ${type})`);

        try {
            // 构建完整路径：直接使用类型前缀 + 文件名
            const fullPath = `${pathPrefix}/${fileName}`;
            console.log(`  完整路径: ${fullPath}`);

            const getResponse = await this.helpers.request({
                method: 'POST',
                uri: `${CONFIG.alist.baseUrl}/api/fs/get`,
                body: { path: fullPath },
                headers: { 'Authorization': CONFIG.alist.token },
                json: true
            });

            if (getResponse.code === 200 && getResponse.data?.raw_url) {
                const finalName = formatFileName(fileName);
                taskFileNames.push(finalName);
                ariaMethods.push({
                    methodName: "aria2.addUri",
                    params: [
                        CONFIG.aria2.token,
                        [getResponse.data.raw_url],
                        {
                            "dir": CONFIG.aria2.dir,
                            "check-certificate": "false",
                            "out": finalName
                        }
                    ]
                });
            }
        } catch (error) {
            console.error(`准备任务失败: ${fileName} (${episodeCode}, ${type})`, error);
        }
    }

    // 3. 批量推送
    if (ariaMethods.length > 0) {
        try {
            const ariaResponse = await this.helpers.request({
                method: 'POST',
                uri: CONFIG.aria2.rpcUrl,
                body: {
                    "jsonrpc": "2.0",
                    "id": Date.now().toString(),
                    "method": "system.multicall",
                    "params": [ariaMethods]
                },
                headers: { 'Content-Type': 'application/json' },
                json: true
            });

            // 核心排查点：解析 multicall 的复杂返回结构
            const finalTasks = [];
            if (ariaResponse.result && Array.isArray(ariaResponse.result)) {
                ariaResponse.result.forEach((res, index) => {
                    // res 通常是一个数组，如 ["gid"] 或 [{code: 1, message: "..."}]
                    const itemResult = res[0]; 

                    if (typeof itemResult === 'string') {
                        // 成功，itemResult 是 GID
                        finalTasks.push({
                            fileName: taskFileNames[index],
                            status: "success",
                            gid: itemResult
                        });
                    } else {
                        // 子任务失败
                        finalTasks.push({
                            fileName: taskFileNames[index],
                            status: "failed",
                            error: itemResult?.message || "未知错误"
                        });
                    }
                });
            }

            results.push({
                json: {
                    status: "complete",
                    summary: `处理完成: ${finalTasks.filter(t => t.status === 'success').length} 成功, ${finalTasks.filter(t => t.status === 'failed').length} 失败`,
                    details: finalTasks
                }
            });

        } catch (error) {
            results.push({ json: { status: "error", msg: "RPC请求发送失败", error: error.message } });
        }
    } else {
        results.push({ json: { status: "warning", msg: "没有搜集到有效的下载任务" } });
    }

    return results;
}

