// 辅助函数：休眠
const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// 辅助函数：获取Bearer Token
function getBearerToken() {
    return $('获取cloudSaverToken').first().json.cloudSaverToken;
}

// 辅助函数：获取文件后缀（小写，无点）
function getFileExtension(fileName) {
    if (!fileName || !fileName.includes('.')) return '';
    return fileName.split('.').pop().toLowerCase();
}

// 辅助函数：检查是否为允许的视频格式
function isAllowedVideoFile(fileName) {
    const ext = getFileExtension(fileName);
    return ALLOWED_EXTENSIONS.has(ext);
}

// 核心：集数匹配函数（支持三重匹配规则：code2, code3, 中文格式）
function getMatchedCode(fileName, targetKeywords, remainingCodes) {
    if (!fileName) return null;

    const name = String(fileName);

    for (const kw of targetKeywords) {
        const { code2, code3, num } = kw;

        // 跳过已匹配完成的集数
        if (remainingCodes && !remainingCodes.has(code2)) continue;

        // 三重匹配规则
        const match2 = name.includes(code2);    // S01E01
        const match3 = name.includes(code3);    // S01E001
        const matchCN = /第\d+集/.test(name) && name.includes(`第${num}集`); // 第X集

        if (match3 || match2 || matchCN) {
            return code2;
        }
    }
    return null;
}

