async function tianyiRecursiveGetFiles(shareCode, pdirFid = '', shareId, receiveCode, targetKeywords, remainingCodes, results) {
    if (remainingCodes.size === 0) return;
    await sleep(SLEEP_TIME);

    const token = getBearerToken();

    try {
        const payload = {
            pwdId: "",
            stoken: "",
            pdirFid: pdirFid,
            shareCode: shareCode,
            receiveCode: receiveCode,
            shareInfo: {
                list: [],
                isFolder: true,
                shareId: shareId,
                shareCode: shareCode,
                receiveCode: receiveCode,
                type: "tianyi"
            }
        };

        const response = await axios.post(`${BASE_URL}/api/tianyi/share-list`, payload, {
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
            },
            timeout: 10000
        });

        if (response.data && response.data.success) {
            const data = response.data.data || {};
            const fileList = data.list || [];

            for (const file of fileList) {
                if (remainingCodes.size === 0) break;

                if (!file.fileName || !file.fileId) continue;

                // 检查是否为视频文件
                if (!isAllowedVideoFile(file.fileName) && !file.isFolder) {
                    console.log(`⏭️ 跳过非视频文件: ${file.fileName}`);
                    continue;
                }

                const matchedCode = getMatchedCode(file.fileName, targetKeywords, remainingCodes);

                if (matchedCode) {
                    // 检查这个集数是否已经匹配过（避免同一集匹配多个文件）
                    if (!remainingCodes.has(matchedCode)) {
                        console.log(`⏭️ 跳过已匹配的集数: ${file.fileName} → ${matchedCode}`);
                        continue;
                    }

                    console.log(`✅ 天翼云盘匹配成功: ${file.fileName} → ${matchedCode}`);

                    results.tianyi[matchedCode] = {
                        shareInfoList: [{
                            fileId: file.fileId,
                            fileName: file.fileName,
                            fileSize: file.fileSize || 0,
                            isFolder: file.isFolder || false,
                            isChecked: true
                        }],
                        fileNames: [file.fileName],
                        shareCode: shareCode,
                        receiveCode: receiveCode,
                        fileId: file.fileId,
                        folderId: DEFAULT_TIANYI_FOLDER,
                        isFolder: true,
                        fids: [file.fileId],
                        shareId: shareId
                    };

                    remainingCodes.delete(matchedCode);
                    console.log(`📌 已匹配集数 ${matchedCode}，剩余待匹配: ${remainingCodes.size}个`);
                }

                if (remainingCodes.size > 0 && file.isFolder) {
                    await tianyiRecursiveGetFiles(
                        shareCode,
                        file.fileId,
                        shareId,
                        receiveCode,
                        targetKeywords,
                        remainingCodes,
                        results
                    );
                }
            }
        }
    } catch (error) {
        console.info(`❌ 天翼云盘请求失败 [${shareCode}/${pdirFid}]:`, error.message);
    }
}

