                    console.error(`❌ 夸克网盘转存请求异常: ${episodeCode}`, error.message);

                    allResults.push({
                        type: 'quark',
                        episodeCode: episodeCode,
                        status: 'error',
                        message: error.message,
                        fileCount: quarkData.fids.length,
                        shareCode: quarkData.shareCode,
                        fileName: quarkData.fileNames[0]
                    });
                }
            } else {
                console.log(`⚠️ 夸克网盘剧集 ${episodeCode} 无有效文件`);
            }
        }
    } else {
        console.log('ℹ️ 夸克网盘无待转存数据');
    }

    // 5. 统计结果
    const totalEpisodes = allResults.length;
    const successEpisodes = allResults.filter(r => r.status === 'success').length;
    const errorEpisodes = allResults.filter(r => r.status === 'error').length;

    console.log('\n📊 转存结果统计:');
    console.log(`   总处理剧集数: ${totalEpisodes}`);
    console.log(`   成功转存剧集: ${successEpisodes}`);
    console.log(`   失败转存剧集: ${errorEpisodes}`);

    // 输出详细结果
    if (errorEpisodes > 0) {
        console.log('\n❌ 失败转存详情:');
        allResults.filter(r => r.status === 'error').forEach(r => {
            console.log(`   ${r.type}[${r.episodeCode}]: ${r.message}`);
        });
    }

    if (successEpisodes > 0) {
        console.log('\n✅ 成功转存详情:');
        allResults.filter(r => r.status === 'success').forEach(r => {
            console.log(`   ${r.type}[${r.episodeCode}]: ${r.fileCount}个文件`);
        });
    }

    console.log('\n🏁 转存脚本执行完成');

    return {
        success: true,
        totalEpisodes: totalEpisodes,
        successEpisodes: successEpisodes,
        errorEpisodes: errorEpisodes,
        details: allResults
    };
}

